ALTER TABLE public.profiles ADD COLUMN academia_id uuid REFERENCES public.academias(id) ON DELETE SET NULL;
CREATE INDEX profiles_academia_idx ON public.profiles(academia_id);
CREATE TABLE public.comentarios (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.posts(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, texto text NOT NULL CHECK (length(trim(texto)) BETWEEN 1 AND 2000), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.comentarios TO anon;
GRANT SELECT, INSERT, DELETE ON public.comentarios TO authenticated;
GRANT ALL ON public.comentarios TO service_role;
ALTER TABLE public.comentarios ENABLE ROW LEVEL SECURITY;
CREATE POLICY "comentarios leitura" ON public.comentarios FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "comentarios cria proprio" ON public.comentarios FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE POLICY "comentarios apaga proprio" ON public.comentarios FOR DELETE TO authenticated USING (auth.uid() = user_id);
CREATE INDEX comentarios_post_idx ON public.comentarios(post_id, created_at);
CREATE TABLE public.stories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, imagem_path text NOT NULL, legenda text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT (now() + interval '24 hours'));
GRANT SELECT ON public.stories TO anon;
GRANT SELECT, INSERT, DELETE ON public.stories TO authenticated;
GRANT ALL ON public.stories TO service_role;
ALTER TABLE public.stories ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.set_story_expiry() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.created_at := clock_timestamp(); NEW.expires_at := NEW.created_at + interval '24 hours'; IF split_part(NEW.imagem_path, '/', 1) <> NEW.user_id::text THEN RAISE EXCEPTION 'Invalid story owner path'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER story_expiry BEFORE INSERT ON public.stories FOR EACH ROW EXECUTE FUNCTION public.set_story_expiry();
CREATE POLICY "stories ativos" ON public.stories FOR SELECT TO anon, authenticated USING (expires_at > now());
CREATE POLICY "stories leitura propria" ON public.stories FOR SELECT TO authenticated USING (auth.uid() = user_id);
CREATE POLICY "stories cria proprio" ON public.stories FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id);
CREATE POLICY "stories apaga proprio" ON public.stories FOR DELETE TO authenticated USING (auth.uid() = user_id);
CREATE INDEX stories_expiry_idx ON public.stories(expires_at);
CREATE POLICY "avatar upload proprio" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'avatars' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "avatar leitura propria" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'avatars' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "avatar remove proprio" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'avatars' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "story upload proprio" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'stories' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "story leitura ativa ou propria" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'stories' AND ((storage.foldername(name))[1] = auth.uid()::text OR EXISTS (SELECT 1 FROM public.stories s WHERE s.imagem_path = name AND s.expires_at > now())));
CREATE POLICY "story remove proprio" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'stories' AND (storage.foldername(name))[1] = auth.uid()::text);